name: Publish Connectors Pre-release Command
on:
  issue_comment:
    types: [created]

permissions: {}

jobs:
  publish-connectors-prerelease:
    if: >
      github.event.issue.pull_request != null &&
      github.event.comment.body == '/publish-connectors-prerelease'
    name: Publish Connectors Pre-release
    runs-on: ubuntu-24.04
    steps:
      - name: Check if user has write access
        id: check-permissions
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: comment } = await github.rest.issues.getComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              comment_id: context.payload.comment.id
            });

            const { data: pullRequest } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            const { data: collaboration } = await github.rest.repos.getCollaboratorPermissionLevel({
              owner: context.repo.owner,
              repo: context.repo.repo,
              username: comment.user.login
            });

            if (collaboration.permission !== 'write' && collaboration.permission !== 'admin') {
              const { data: teamMembership } = await github.rest.teams.getMembershipForUserInOrg({
                org: context.repo.owner,
                team_slug: 'connectors',
                username: comment.user.login
              });
              if (!teamMembership) {
                throw new Error(`User ${comment.user.login} does not have write access or team membership`);
              }
            }

      - name: Get PR information
        id: pr-info
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: pullRequest } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            const { data: commits } = await github.rest.pulls.listCommits({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            const lastCommit = commits[commits.length - 1];
            const sha = lastCommit.sha;

            const { data: status } = await github.rest.repos.getCombinedStatusForRef({
              owner: context.repo.owner,
              repo: context.repo.repo,
              ref: sha
            });

            const checks = status.statuses.filter(status => status.context.startsWith('Connector CI Checks'));

            const modifiedConnectors = [];
            const { data: files } = await github.rest.pulls.listFiles({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            const connectorDirs = new Set();
            for (const file of files) {
              const pathParts = file.filename.split('/');
              if (pathParts.length >= 2 && pathParts[0] === 'airbyte-integrations' && pathParts[1] === 'connectors') {
                const connectorDir = pathParts.slice(0, 3).join('/');
                connectorDirs.add(connectorDir);
              }
            }

            for (const dir of connectorDirs) {
              modifiedConnectors.push(dir.split('/').pop());
            }

            const prTitle = pullRequest.title;
            const prNumber = context.issue.number;

            console.log(`PR Title: ${prTitle}`);
            console.log(`PR Number: ${prNumber}`);
            console.log(`SHA: ${sha}`);
            console.log(`Modified Connectors: ${modifiedConnectors.join(', ')}`);

            const commentBody = `Starting pre-release build for modified connectors: ${modifiedConnectors.join(', ')}\n\nExpected image tag format: \`${modifiedConnectors.map(c => `${c}:dev.${sha.substring(0, 10)}`).join(', ')}\``;

            core.setOutput('pr_title', prTitle);
            core.setOutput('pr_number', prNumber);
            core.setOutput('sha', sha);
            core.setOutput('modified_connectors', JSON.stringify(modifiedConnectors));
            core.setOutput('comment_body', commentBody);

      - name: Post start comment
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: comment } = await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: `${{ steps.pr-info.outputs.comment_body }}`
            });

      - name: Call publish_connectors workflow
        id: call-workflow
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: workflowRun } = await github.rest.actions.createWorkflowDispatch({
              owner: context.repo.owner,
              repo: context.repo.repo,
              workflow_id: 'publish_connectors.yml',
              ref: 'main',
              inputs: {
                'release-type': 'pre-release',
                'modified': '${{ steps.pr-info.outputs.modified_connectors }}'
              }
            });

            core.setOutput('workflow_run_id', workflowRun.id);

      - name: Wait for workflow completion
        uses: actions/github-script@v7
        id: wait-for-workflow
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const workflowId = ${{ steps.call-workflow.outputs.workflow_run_id }};
            let completed = false;
            let status = '';

            while (!completed) {
              const { data: workflowRun } = await github.rest.actions.getWorkflowRun({
                owner: context.repo.owner,
                repo: context.repo.repo,
                run_id: workflowId
              });

              status = workflowRun.conclusion;
              completed = status !== null && status !== 'queued' && status !== 'in_progress';

              if (!completed) {
                await new Promise(r => setTimeout(r, 10000)); // Wait 10 seconds before checking again
              }
            }

            core.setOutput('status', status);

      - name: Post completion comment
        uses: actions/github-script@v7
        if: always()
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: comment } = await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: `${{ 
                steps.wait-for-workflow.outputs.status == 'success' 
                ? ':white_check_mark: Pre-release build completed successfully!' 
                : ':x: Pre-release build failed!'
              }}`
            });
